import{_ as e,o as d,c as o,a0 as n}from"./chunks/framework.BGyYNsHo.js";const h=JSON.parse('{"title":"New engine options","description":"","frontmatter":{},"headers":[],"relativePath":"reference/01-engine-options.md","filePath":"reference/01-engine-options.md"}'),r={name:"reference/01-engine-options.md"};function i(a,t,c,s,l,_){return d(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="new-engine-options" tabindex="-1">New engine options <a class="header-anchor" href="#new-engine-options" aria-label="Permalink to &quot;New engine options&quot;">​</a></h1><p>The following table summarizes the options and sections that HydroCouple adds on top of official SWMM.</p><table tabindex="0"><thead><tr><th>Option / section</th><th>What it adds</th><th>Default value</th></tr></thead><tbody><tr><td><code>NODE_CONTINUITY</code></td><td>unified semi-implicit node continuity</td><td>EXPLICIT (legacy)</td></tr><tr><td><code>ANDERSON_ACCEL</code></td><td>Anderson acceleration of the Picard loop</td><td>NO</td></tr><tr><td><code>SURCHARGE_METHOD</code></td><td>third surcharge method: DYNAMIC_SLOT</td><td>EXTRAN (legacy)</td></tr><tr><td><code>DPS_CELERITY</code> / <code>DPS_ALPHA</code> / <code>DPS_DECAY_TIME</code></td><td>dynamic slot parameters</td><td>25 m/s, 3, 0.5 s</td></tr><tr><td><code>[VIRTUAL_JUNCTIONS]</code></td><td>sealed zero-storage nodes with momentum transmission</td><td>---</td></tr><tr><td><code>VIRTUAL_JUNCTION_MOMENTUM</code></td><td>convective correction across the virtual junction</td><td>BASIC</td></tr><tr><td><code>FLOW_ROUTING FV</code></td><td>explicit 1D finite volume solver</td><td>DYNWAVE (legacy)</td></tr><tr><td><code>FV_*</code></td><td>FV solver options (CFL, Riemann, order, LTS, ...)</td><td>see the <a href="./../explanation/engine-modifications/06-finite-volume-routing.html">FV solver options table</a></td></tr><tr><td><code>[2D_VERTICES]</code><br><code>[2D_TRIANGLES]</code></td><td>local-inertial shallow water 2D mesh</td><td>---</td></tr><tr><td><code>[2D_OPTIONS]</code></td><td>2D marching scheme and coupling options (<code>COUPLING_CD</code>, <code>COUPLING_SYNC</code>, ...)</td><td>COUPLING_CD 0.65</td></tr><tr><td><code>IGNORE_2D</code></td><td>disables the 2D solver while keeping the mesh</td><td>NO</td></tr><tr><td><code>[RDII_DECAY]</code></td><td>exponential recovery of the RDII abstraction with temperature ($k_0$, $k_T$, $T_{\\mathrm{ref}}$)</td><td>---</td></tr><tr><td><code>THREADS</code></td><td>bit-exact OpenMP solver threads</td><td>1</td></tr><tr><td><code>CRS</code></td><td>spatial reference system (EPSG/PROJ)</td><td>empty</td></tr><tr><td><code>SKIP_STEADY_STATE</code></td><td>skips routing in steady state</td><td>NO</td></tr></tbody></table><p><em>Table: New OpenSWMM engine options and sections with respect to official US EPA SWMM.</em></p>',4)])])}const m=e(r,[["render",i]]);export{h as __pageData,m as default};
